import {actTwoContent as C} from './act-two-content.mjs';
import {actTwoChapters,actTwoView,actTwoCandidates,startActTwo,offerActTwo,celebrateActTwo,revealFloodLedger,openUpstreamLetter,addStormMark,setActTwoPageAmount,setActTwoFrameAmount,setLetterAmount} from './act-two-core.mjs';
import {storyView} from './keeper-story-core.mjs';
import {guides} from './companions.mjs';
import {courierPresets,postCourierIdentity} from './post-office-content.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const link=(href,label,primary=false)=>`<a class="${primary?'primary':'secondary'}" href="${href}">${esc(label)}</a>`;
const paras=lines=>lines.map(x=>`<p>${esc(x)}</p>`).join('');
const reading=lines=>`<div data-act-two-read>${paras(lines)}</div>`;
const heading=title=>`<h2 data-act-two-heading tabindex="-1">${esc(title)}</h2>`;
const back=()=>link('#almanac/town',C.ui.back);
const hear=()=>hearButton('',C.ui.hear,'en');
function amounts(v,kind){const key=kind==='frame'?'frameAmount':kind==='letter'?'letterAmount':'pageAmount',bad=v[`${key}Status`]==='unreadable',keys=kind==='page'?['short','longer','original']:['short','longer'];return `<div class="act-two-controls" role="group" aria-label="${kind==='frame'?'Story':kind==='letter'?'Letter':'Page'} reading amount">${keys.map(k=>button(`data-act-two-${kind}-amount="${k}" aria-pressed="${v[key]===k}"${bad?' disabled':''}`,C.ui[k],v[key]===k)).join('')}</div>${bad?`<p role="status">${esc(C.messages.badPreference)}</p>`:''}`;}
function townArt(){return `<figure class="act-two-art"><svg viewBox="0 0 760 330" role="img" aria-label="${esc(C.celebration.artDescription)}"><rect width="760" height="330" rx="20" fill="#fffdf6"/><path d="M0 250Q150 175 340 245T760 230V330H0Z" fill="#d5dfbd"/><path d="M0 294Q189 243 359 299T760 278" fill="none" stroke="#78b7cf" stroke-width="36"/><path d="M505 303v-42q40-28 80 0v42m-82-44h84" fill="#b99b73" stroke="#203f58" stroke-width="4"/><path d="M45 170V81h163v129H45M32 82l96-54 95 54Z" fill="#e7d7b7" stroke="#203f58" stroke-width="4"/><path d="M82 105h87v70H82Z" fill="#e8bc58" stroke="#203f58" stroke-width="3"/><path d="M92 117h25v43H92Zm36 0h27v43h-27Z" fill="#fffdf6" stroke="#b99b73" stroke-width="2"/><path d="M70 180h112" stroke="#203f58" stroke-width="5"/><path d="M271 220h153v22H271Zm14 22v35m127-35v35" fill="#b99b73" stroke="#203f58" stroke-width="4"/><path d="M318 195h57v25h-57Z" fill="#fffdf6" stroke="#203f58" stroke-width="3"/><path d="M346 194v-17" stroke="#203f58" stroke-width="3"/><path d="M346 177q-10-8 0-17q10 9 0 17" fill="#e8bc58"/><path d="M573 193V92h144v101Zm-10 0h164v18H563Z" fill="#b99b73" stroke="#203f58" stroke-width="4"/><path d="M583 103h124v80H583Z" fill="#78b7cf"/><path d="M584 103h29l-9 69-21 10Zm123 0h-29l9 69 20 10Z" fill="#b47974"/><path d="M616 175q25-35 47 0m-21-22v-22" stroke="#203f58" stroke-width="4" fill="none"/><circle cx="642" cy="124" r="9" fill="#fffdf6" stroke="#203f58" stroke-width="3"/><path d="M40 28Q355 120 729 29" fill="none" stroke="#203f58" stroke-width="3"/>${[[85,40],[205,65],[330,73],[459,69],[587,52],[697,34]].map(([x,y])=>`<path d="M${x} ${y}v17" stroke="#203f58" stroke-width="2"/><rect x="${x-9}" y="${y+17}" width="18" height="24" rx="5" fill="#e8bc58" stroke="#203f58" stroke-width="2"/>`).join('')}<path d="M468 230h30l8 37h-45Z" fill="#b99b73" stroke="#203f58" stroke-width="3"/><path d="M475 231q8-23 17 0m-21 13h20" fill="none" stroke="#203f58" stroke-width="3"/></svg></figure>`;}
export function actTwoInvitation(state,{blocked=false}={}){const v=actTwoView(state);if(!v.started&&!storyView(state).pageVisible)return '';return `<aside class="act-two-invitation" data-keeper-invite data-keeper-story${blocked?' hidden':''}><h2 data-keeper-heading tabindex="-1">${esc(C.title)}</h2><p>${esc(v.ended?C.celebration.short[0]:v.started?C.ui.instruction:C.opening.short[0])}</p><div class="act-two-controls">${link('#almanac/town',v.started?'Return to the town gathering':C.ui.start,true)}${v.ended?link('#almanac/celebration',C.ui.celebrationReplay):''}${link('#almanac/keepers',C.ui.oldMap)}</div></aside>`;}
export function actTwoReturn(state,chapter){return actTwoView(state).started&&actTwoChapters.includes(chapter)?`<aside class="act-two-return"><a class="secondary" data-act-two-return="${chapter}" href="#almanac/town/${chapter}">${esc(C.ui.hostReturn)}</a></aside>`:'';}
function chapterStrip(v,selected){return `<nav class="act-two-chapters" aria-label="${esc(C.ui.chooseChapter)}">${actTwoChapters.map(k=>`<a href="#almanac/town/${k}" data-act-two-chapter="${k}"${k===selected?' aria-current="page"':''}>${esc(C.chapters[k].title)}${v.chapterStatus[k]==='ready'?`<small>${esc(C.ui.offered)}</small>`:''}</a>`).join('')}</nav>`;}
function progress(v){return `<p class="act-two-progress">${esc(C.ui.progress.replace('{n}',v.count))}</p>${v.ended?link('#almanac/celebration',C.ui.celebrationReplay,true):v.canCelebrate?`<p>${esc(C.ui.ready)}</p>${button('data-act-two-celebrate',C.ui.celebrate,true)}`:`<p>${esc(v.endedStatus==='unreadable'||v.contributionsStatus==='unreadable'?C.messages.unreadableAct:C.ui.beforeReady)}</p>`}`;}
function chapterBody(v,key){const c=C.chapters[key],s=v.sources[key];let offer;
 if(v.chapterStatus[key]==='ready')offer=`<p class="act-two-kept">${esc(c.after)}</p><p>${esc(C.messages.alreadyOffered)}</p>`;
 else if(v.chapterStatus[key]==='unreadable'||!v.canOffer)offer=`<p>${esc(C.messages.unreadableReceipt)}</p>`;
 else if(s.candidates.length)offer=`<label for="act-two-candidate">${esc(c.selector)}</label><select id="act-two-candidate" data-act-two-candidate="${key}">${s.candidates.map(x=>`<option value="${esc(x.key)}">${esc(x.label)}</option>`).join('')}</select>${button(`data-act-two-offer="${key}"`,c.offer,true)}`;
 else offer=`<p>${esc(c.noWork)}</p>`;
 return `<section class="act-two-folio">${heading(c.title)}${reading(c[v.frameAmount])}<p>${esc(c.job)}</p>${link(c.hostHref,c.hostLabel,true)}<div class="act-two-offer">${offer}${s.retainedUnreadable?`<p>${esc(C.messages.unavailableWork)}</p>`:''}</div></section>`;}
function town(v,chapter){if(['unavailable','unreadable'].includes(v.status))return `${heading(C.title)}<p>${esc(C.messages.unreadableAct)}</p>${link('#notes','Open Grown-up notes')}${link('#almanac/keepers',C.ui.oldMap)}`;
 if(!v.started)return `${heading(C.title)}${amounts(v,'frame')}${reading(C.opening[v.frameAmount])}${hear()}${v.canStart?button('data-act-two-start',C.ui.start,true):`<p>${esc((v.startedStatus==='unreadable'?C.messages.unreadableAct:C.ui.beforePageOne))}</p>${link('#almanac/keepers',C.ui.oldMap,true)}`}`;
 return `${amounts(v,'frame')}<p>${esc(C.ui.instruction)}</p>${chapterStrip(v,chapter)}${chapter?chapterBody(v,chapter):`${heading(C.ui.chooseChapter)}${reading(C.opening[v.frameAmount])}`}${hear()}<section class="act-two-next">${progress(v)}</section>`;
}
function celebration(v){if(!v.ended)return `${heading(C.title)}<p>${esc(C.messages.unreached)}</p>${back()}`;return `${heading(C.celebration.title)}${townArt()}${amounts(v,'frame')}${reading([...C.celebration[v.frameAmount],...(v.season?[C.celebration.seasons[v.season]]:[])])}${hear()}<div class="act-two-controls">${v.pageVisible?link('#almanac/flood-ledger',C.ui.readSecondPage,true):button('data-act-two-reveal-page',C.ui.readSecondPage,true)}${back()}</div>`;}
function floodPage(state,v){if(!v.pageReady)return `${heading(C.page.title)}<p>${esc(C.messages.unreached)}</p>${back()}`;
 if(!v.pageVisible)return `${heading(C.page.title)}${reading([C.page.reveal])}${hear()}${button('data-act-two-reveal-page',C.ui.readSecondPage,true)}`;
 const guide=guides.find(g=>g.id===state.garden?.guide)||guides[0],p=C.page;
 return `${heading(p.title)}${amounts(v,'page')}${reading(p[v.pageAmount==='longer'?'longer':'short'])}<figure class="act-two-ledger" data-act-two-read><table><thead><tr>${p.headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${p.rows.map(r=>`<tr><th scope="row">${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table><figcaption>${esc(p.datum)} ${esc(p.caption)}</figcaption></figure>${v.pageAmount==='original'?`<section data-act-two-read><h3>${esc(p.originalLabel)}</h3><blockquote>${esc(p.original)}</blockquote><p>${esc(p.explanation)}</p></section>`:''}${reading([p.guideLine.replace('{guide}',guide.name)])}${v.stormAdded?`<aside class="act-two-storm" data-act-two-read><h3>${esc(p.stormResult)}</h3><p>${esc(p.stormExplanation)}</p></aside>`:`${reading([p.stormInvitation])}${button('data-act-two-add-storm',p.stormButton)}`}${hear()}<div class="act-two-glossary" aria-label="Words on the page">${Object.entries(p.glossary).map(([k,x])=>`<details><summary>${esc(k)}</summary><p data-act-two-read>${esc(x)}</p></details>`).join('')}</div><div class="act-two-controls">${link('#almanac/upstream-letter',C.ui.letterOffer,true)}${link('#almanac/celebration',C.ui.celebrationReplay)}${back()}</div>`;
}
function upstream(state,v){if(!v.letterReady)return `${heading(C.ui.letterOffer)}<p>${esc(C.messages.unreached)}</p>${back()}`;
 const courier=courierPresets.some(x=>x.id===state.postOffice?.courier)?`the ${postCourierIdentity(state).title.toLowerCase()}`:'the courier',invitation=C.letter.invitation.replace('{courier}',courier);
 if(!v.letterVisible)return `${heading(C.ui.letterOffer)}${reading([invitation])}${hear()}${button('data-act-two-open-letter',C.ui.openLetter,true)}`;
 return `${heading(C.letter.title)}${amounts(v,'letter')}<article class="act-two-letter" data-act-two-read>${paras(C.letter[v.letterAmount])}<p class="act-two-caption">${esc(C.letter.caption)}</p></article>${reading([C.letter.close,C.letter.almanacLine,C.letter.betweenVisits])}${hear()}<nav class="act-two-controls" aria-label="Next places">${link('#post',C.ui.visitPost,true)}${link('#explore',C.ui.explore)}${back()}${link('#almanac/flood-ledger',C.ui.readSecondPage)}${link('#home',C.ui.pause)}</nav>`;
}
export function actTwoPage(state,{part='town',chapter=null,blocked=false}={}){const v=actTwoView(state),selected=actTwoChapters.includes(chapter)?chapter:null;let body;
 if(['unavailable','unreadable'].includes(v.status))body=town(v,null);
 else body=part==='celebration'?celebration(v):part==='flood-ledger'?floodPage(state,v):part==='upstream-letter'?upstream(state,v):town(v,selected);
 return `<div class="act-two-page" data-act-two-root data-keeper-story lang="en"${blocked?' hidden':''}><header><a class="back" href="#home">Back to the garden</a><h1>${esc(C.title)}</h1><p>${esc(C.label)}</p></header>${body}<p id="act-two-status" role="status" aria-live="polite" tabindex="-1"></p><footer class="act-two-controls">${link('#almanac/keepers',C.ui.oldMap)}${link('#explore',C.ui.explore)}${link('#notes','Grown-up notes')}</footer></div>`;
}
export function actTwoNotes(state){const v=actTwoView(state);if(v.status==='missing')return '';return `<details class="panel"><summary>${esc(C.notes.title)}</summary><p>${esc(C.notes.description)}</p>${['unavailable','unreadable'].includes(v.status)?`<p>${esc(C.messages.unreadableAct)}</p>`:`<ul>${actTwoChapters.map(k=>`<li>${esc(C.chapters[k].title)}: ${esc(v.chapterStatus[k]==='ready'?C.notes.offered:v.chapterStatus[k]==='unreadable'?C.notes.unreadable:'not yet offered')}</li>`).join('')}</ul><p>${esc(v.ended?C.notes.ended:C.notes.notEnded)}. Second page read: ${v.pageVisible?'yes':'not yet'}. Letter opened: ${v.letterVisible?'yes':'not yet'}.</p>`}</details>`;}
export function bindActTwo(state,{save,render,focus,canExport,explorerId,isActive}){const root=document.querySelector('[data-act-two-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,record=state.story;
 const live=el=>root.isConnected&&document.querySelector('[data-act-two-root]')===root&&root.contains(el)&&el.isConnected&&state.story===record&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner&&!root.hidden&&!document.querySelector('dialog.welcome-film[open]');
 const status=text=>{const el=root.querySelector('#act-two-status');el.textContent=text;el.focus();};
 const options={canExport};
 const redraw=(destination=null,target='[data-act-two-heading]')=>{stopSpeech();save();if(destination&&destination!==location.hash){window.addEventListener('hashchange',()=>{if(explorerId?.()===owner&&(!isActive||isActive())&&location.hash===destination)focus?.(target);},{once:true});location.hash=destination;}else{render();focus?.(target);}};
 const bind=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(live(b))fn(b);}));
 const commit=(fn,dest=null,target)=>{if(!fn())return status(C.messages.saveRefused);redraw(dest,target);};
 bind('[data-act-two-start]',()=>{if(!actTwoView(state).canStart)return status(C.ui.beforePageOne);commit(()=>startActTwo(state,options));});
 bind('[data-act-two-offer]',b=>{const chapter=b.dataset.actTwoOffer,v=actTwoView(state),key=root.querySelector(`[data-act-two-candidate="${chapter}"]`)?.value;if(v.chapterStatus[chapter]==='ready')return status(C.messages.alreadyOffered);if(!v.canOffer||v.chapterStatus[chapter]==='unreadable')return status(C.messages.unreadableReceipt);if(!actTwoCandidates(state,chapter).some(x=>x.key===key))return status(C.messages.missingCandidate);commit(()=>offerActTwo(state,chapter,key,options));});
 bind('[data-act-two-celebrate]',()=>{if(!actTwoView(state).canCelebrate)return status(C.messages.ineligibleCelebration);commit(()=>celebrateActTwo(state,new Date().getMonth(),options),'#almanac/celebration');});
 bind('[data-act-two-reveal-page]',()=>{if(!actTwoView(state).pageReady)return status(C.messages.unreached);commit(()=>revealFloodLedger(state,options),'#almanac/flood-ledger');});
 bind('[data-act-two-open-letter]',()=>{if(!actTwoView(state).letterReady)return status(C.messages.unreached);commit(()=>openUpstreamLetter(state,options),'#almanac/upstream-letter');});
 bind('[data-act-two-add-storm]',()=>{if(!actTwoView(state).pageVisible)return status(C.messages.unreached);commit(()=>addStormMark(state,options));});
 for(const [kind,fn] of [['frame',setActTwoFrameAmount],['page',setActTwoPageAmount],['letter',setLetterAmount]])bind(`[data-act-two-${kind}-amount]`,b=>commit(()=>fn(state,b.getAttribute(`data-act-two-${kind}-amount`),options),null,`[data-act-two-${kind}-amount="${b.getAttribute(`data-act-two-${kind}-amount`)}"]`));
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=[...root.querySelectorAll('[data-act-two-read]')].filter(x=>x.getClientRects().length&&getComputedStyle(x).visibility!=='hidden').map(x=>x.innerText).join(' ').replaceAll('[smudged word]','a smudged word');},{capture:true}));
}
